#!/bin/bash
# The samples' generated or third-party assets, which git ignores (too large, user 11-11): each folder below keeps
# them beside its samples, regenerated by the scripts its NOTICE.md names, and published as one archive per folder on
# the GitHub release `assets`, so the page (pages.yml, build.sh collect_site) and a fresh checkout or worktree have them.
#   scripts/sample-assets.sh fetch [<folder>…]    unpack the published archive into each folder missing its assets
#   scripts/sample-assets.sh publish [<folder>…]  upload each folder's ignored files as its archive (replaces the old)
#   scripts/sample-assets.sh list [<folder>…]     the ignored files the folders hold, one path a line
set -euo pipefail

ASSET_FOLDERS=(samples/graphics/ez_trees)
RELEASE=assets
REPOSITORY=pannous/warp
RELEASE_URL=https://github.com/$REPOSITORY/releases/download/$RELEASE

cd "$(dirname "$0")/.."
command=${1:-}
shift || true
folders=("${@:-${ASSET_FOLDERS[@]}}")

archive_name() { echo "${1//\//_}.tar.gz"; }

ignored_files() { git -c core.quotepath=off ls-files --others --ignored --exclude-standard -- "$1" | grep -v '/\.DS_Store$' || true; }

fetched() {
	local folder=$1 name
	name=$(archive_name "$folder")
	[ -n "$(ignored_files "$folder")" ] && { echo "$folder: has its assets"; return; }
	echo "$folder: fetching $RELEASE_URL/$name"
	curl -fsSL "$RELEASE_URL/$name" | tar -xzf - -C "$folder"
}

published() {
	local folder=$1 name files
	name=$(archive_name "$folder")
	files=$(ignored_files "$folder")
	[ -n "$files" ] || { echo "$folder: no assets to publish (generate them first: $folder/NOTICE.md)" >&2; exit 1; }
	gh release view "$RELEASE" --repo "$REPOSITORY" >/dev/null 2>&1 ||
		gh release create "$RELEASE" --repo "$REPOSITORY" --prerelease --title "$RELEASE" \
			--notes "The samples' generated assets, which git ignores: scripts/sample-assets.sh fetch"
	sed "s|^$folder/||" <<<"$files" | tar -czf "$name" -C "$folder" -T -
	gh release upload "$RELEASE" "$name" --repo "$REPOSITORY" --clobber && rm "$name"
	echo "$folder: published $RELEASE_URL/$name"
}

for folder in "${folders[@]}"; do
	case $command in
	fetch) fetched "$folder" ;;
	publish) published "$folder" ;;
	list) ignored_files "$folder" ;;
	*) sed -n '2,7p' "$0" | cut -c3- >&2; exit 2 ;;
	esac
done
